from core import *
from models import csvwrite
from collections import Counter,defaultdict
from scipy.stats import spearmanr

def ci(x):return np.quantile(x,[.025,.975],axis=0)
def difference(lo,hi,blo,bhi,a,b):
    if a==b:return dict(point=0.,bounds=[0.,0.],CI95_point=[0.,0.],CI95_unknown_envelope=[0.,0.])
    return dict(point=float(lo[a]-lo[b]),bounds=[float(lo[a]-hi[b]),float(hi[a]-lo[b])],CI95_point=ci(blo[:,a]-blo[:,b]),CI95_unknown_envelope=[float(ci(blo[:,a]-bhi[:,b])[0]),float(ci(bhi[:,a]-blo[:,b])[1])])
def status(certain,possible):return 'SUPPORTED' if certain else 'REJECTED' if not possible else 'INCONCLUSIVE'

def statistics(Y,U,names,arms,selectors):
    n=len(names);y=Y.mean(-1);u=U.mean(-1);lo=y.mean(-1);hi=(y+u).mean(-1);rng=np.random.default_rng(202610131201);weights=np.array([np.bincount(z,minlength=64)/64 for z in rng.integers(0,64,(5000,64))]);bl=np.einsum('bs,cas->bca',weights,y);bh=np.einsum('bs,cas->bca',weights,y+u);oracle=lo.max(1);bo=bl.max(2);effects={};effect_rows=[];arm_rows=[]
    for i,name in enumerate(names):
        effects[name]={}
        for label,a,b in [('E',3,0),('L',3,1),('N',1,0)]:
            d=difference(lo[i],hi[i],bl[:,i],bh[:,i],a,b);effects[name][label]=d;effect_rows.append(dict(controller=name,effect=label,point=d['point'],unknown_lower=d['bounds'][0],unknown_upper=d['bounds'][1],CI95_lower=d['CI95_point'][0],CI95_upper=d['CI95_point'][1],CI95_envelope_lower=d['CI95_unknown_envelope'][0],CI95_envelope_upper=d['CI95_unknown_envelope'][1]))
        for a,arm in enumerate(arms):arm_rows.append(dict(controller=name,arm=arm,success_count=int(Y[i,a].sum()),unknown_count=int(U[i,a].sum()),success_lower=lo[i,a],success_upper=hi[i,a],CI95_lower=float(ci(bl[:,i,a])[0]),CI95_upper=float(ci(bl[:,i,a])[1]),CI95_envelope_lower=float(ci(bl[:,i,a])[0]),CI95_envelope_upper=float(ci(bh[:,i,a])[1])))
    E=lo[:,3]-lo[:,0];L=lo[:,3]-lo[:,1];assert np.max(abs(E-L-(lo[:,1]-lo[:,0])))<1e-14
    out={};method_rows=[];prediction_metrics={}
    for scheme in ['primary','secondary','source_average','prior_F10']:
        choices=[selectors[name][scheme+'_action'] if scheme in ['primary','secondary'] else 'S500' if scheme=='source_average' else 'F10' for name in names];ids=np.array([arms.index(a) for a in choices]);chosen_lo=lo[np.arange(n),ids];chosen_hi=hi[np.arange(n),ids];regret=oracle-chosen_lo;reglow=[];reghi=[];brl=[];brh=[];gp=[];glo=[];ghi=[];gpoints=[];glos=[];ghis=[];dspoints=[];dslows=[];dshighs=[]
        for i,a in enumerate(ids):
            other=[j for j in range(6) if j!=a];reglow.append(max([0.]+[lo[i,j]-hi[i,a] for j in other]));reghi.append(max([0.]+[hi[i,j]-lo[i,a] for j in other]));brl.append(np.maximum(0,np.max(bl[:,i,other]-bh[:,i,a,None],axis=1)));brh.append(np.maximum(0,np.max(bh[:,i,other]-bl[:,i,a,None],axis=1)))
            gain=difference(lo[i],hi[i],bl[:,i],bh[:,i],int(a),0);sourcegain=difference(lo[i],hi[i],bl[:,i],bh[:,i],int(a),3);gp.append(gain['point']);glo.append(gain['bounds'][0]);ghi.append(gain['bounds'][1]);gpoints.append(bl[:,i,a]-bl[:,i,0]);glos.append(np.zeros(5000) if a==0 else bl[:,i,a]-bh[:,i,0]);ghis.append(np.zeros(5000) if a==0 else bh[:,i,a]-bl[:,i,0]);dspoints.append(bl[:,i,a]-bl[:,i,3]);dslows.append(np.zeros(5000) if a==3 else bl[:,i,a]-bh[:,i,3]);dshighs.append(np.zeros(5000) if a==3 else bh[:,i,a]-bl[:,i,3])
            method_rows.append(dict(controller=names[i],method=scheme,selected_arm=arms[a],success_lower=chosen_lo[i],success_upper=chosen_hi[i],oracle_arm=arms[int(lo[i].argmax())],oracle_lower=oracle[i],regret=regret[i],regret_lower=reglow[-1],regret_upper=reghi[-1],gain_vs_F10=gp[-1],gain_lower=glo[-1],gain_upper=ghi[-1],gain_vs_source_average=sourcegain['point']))
        breg=bo-bl[:,np.arange(n),ids];bg=np.mean(gpoints,axis=0);bglo=np.mean(glos,axis=0);bghi=np.mean(ghis,axis=0);ds=np.mean(dspoints,axis=0);dsl=np.mean(dslows,axis=0);dsh=np.mean(dshighs,axis=0);bc=ci(bg);bc_lo=ci(bglo);bc_hi=ci(bghi);dc=ci(ds);dc_lo=ci(dsl);dc_hi=ci(dsh);reglow=np.asarray(reglow);reghi=np.asarray(reghi)
        full=n==8;pointC1=bool(bc[0]>0 and regret.mean()<=.02 and np.min(gp)>=-.10);certainC1=bool(full and bc_lo[0]>0 and reghi.mean()<=.02 and np.min(glo)>=-.10);possibleC1=bool(bc_hi[0]>0 and reglow.mean()<=.02 and np.min(ghi)>=-.10);C1=status(certainC1,possibleC1) if full else 'INCONCLUSIVE';C1b=status(bool(reghi.max()<=.05),bool(reglow.max()<=.05)) if full else 'INCONCLUSIVE'
        count=int((E<.05).sum());count_min=sum(effects[name]['E']['bounds'][1]<.05 for name in names);count_max=sum(effects[name]['E']['bounds'][0]<.05 for name in names)
        headroom=count>=2
        if not full or not headroom:C2='INCONCLUSIVE';reason='No point headroom (fewer than two E<5pp)' if full else 'Fewer than8 compatible final controllers'
        elif count_min<2:C2='INCONCLUSIVE';reason='Headroom threshold can flip under unknown'
        else:C2=status(bool(dc_lo[0]>0),bool(dc_hi[0]>0));reason='Paired state-cluster improvement CI; oracle cancels exactly'
        out[scheme]=dict(selected_arms=choices,mean_regret=float(regret.mean()),max_regret=float(regret.max()),mean_regret_unknown_bounds=[float(reglow.mean()),float(reghi.mean())],max_regret_unknown_bounds=[float(reglow.max()),float(reghi.max())],mean_regret_CI95=ci(breg.mean(1)),mean_regret_CI95_unknown_envelope=[float(ci(np.mean(brl,axis=0))[0]),float(ci(np.mean(brh,axis=0))[1])],mean_gain_vs_F10=float(np.mean(gp)),gain_vs_F10_CI95=bc,gain_vs_F10_CI95_unknown_envelope=[bc_lo[0],bc_hi[1]],per_controller_gain_vs_F10=gp,per_controller_gain_bounds=np.c_[glo,ghi],mean_gain_vs_source_average=float(ds.mean()),gain_vs_source_average_CI95=dc,gain_vs_source_average_CI95_unknown_envelope=[dc_lo[0],dc_hi[1]],C1=C1,C1_point_pass=pointC1,C1b=C1b,C1b_point_pass=bool(regret.max()<=.05),C2=C2,C2_point_pass=bool(headroom and dc[0]>0),C2_reason=reason,headroom_count=count,headroom_count_unknown_range=[count_min,count_max],headroom_point_pass=headroom,catastrophic_vs_F10_point=[names[i] for i in range(n) if gp[i]<-.10],regret_exceeds5pp_point=[names[i] for i in range(n) if regret[i]>.05],choices=[row for row in method_rows if row['method']==scheme])
        if scheme in ['primary','secondary']:
            pred=np.array([selectors[name][scheme+'_Ehat'] for name in names]);baseline=np.array([selectors[name][scheme+'_source_mean_E'] for name in names]);rmse=float(np.sqrt(np.mean((pred-E)**2)));base_rmse=float(np.sqrt(np.mean((baseline-E)**2)));rho=float(spearmanr(pred,E).statistic) if np.ptp(pred)>0 and np.ptp(E)>0 else None;pointpass=bool(rho is not None and rho>=.6 and rmse<=.7*base_rmse);prediction_metrics[scheme]=dict(Spearman=rho,RMSE=rmse,source_mean_baseline_RMSE=base_rmse,RMSE_ratio=rmse/base_rmse if base_rmse else None,C3_point_pass=pointpass,C3='SUPPORTED' if full and pointpass else 'REJECTED' if full else 'INCONCLUSIVE',controller_order=names,predictions=pred,actual_E=E,source_mean_predictions=baseline,interpretation='Prospective fixed model against registered conservative lower-rate E point labels; unknown success intervals retained separately')
    C4=dict(status='INCONCLUSIVE',kind='DESCRIPTIVE_NO_REGISTERED_BINARY_THRESHOLD',E_positive=int((E>0).sum()),L_positive=int((L>0).sum()),both_E_L_ge10pp=int(((E>=.1)&(L>=.1)).sum()),N_negative=int(((E-L)<0).sum()),N_positive=int(((E-L)>0).sum()),N_zero=int(((E-L)==0).sum()),cohort_n=n,round10_best_reference=dict(cohort_n=14,E_positive=11,L_positive=14,both_E_L_ge10pp=10),unknown_sign_count_ranges={k:[sum(effects[n][k]['bounds'][0]>0 for n in names),sum(effects[n][k]['bounds'][1]>0 for n in names)] for k in ['E','L']})
    return dict(methods=out,prediction_metrics=prediction_metrics,C4=C4,effects=effects,bootstrap=dict(seed=202610131201,draws=5000,state_clusters=64,future_seeds_retained=4,shared_draws_across_controllers_arms=True,controller_resampling=False,selectors_frozen=True)),method_rows,arm_rows,effect_rows

def main():
    prereg();labels_allowed();gate();p=read(HERE/'protocol.json');names=p['controller_order'];arms=p['arms'];cases=read(HERE/'main_CASES.json');assert len(cases)==len(names)*1536;paths=[HERE/'main/raw'/f"{c['rollout_uid']}.json" for c in cases];assert all(q.exists() for q in paths)
    inventory=[dict(rollout_uid=c['rollout_uid'],sha256=sha(q)) for c,q in zip(cases,paths)];opening=HERE/'ENDPOINT_OPENING.receipt.json'
    if opening.exists():assert read(opening)['raw_inventory']==inventory
    else:write(opening,dict(utc=utc(),raw_inventory=inventory,records=len(paths),all_requested_raw_present=True,selector_receipt_sha256=sha(HERE/'SELECTOR_FROZEN.receipt.json'),probe_receipt_sha256=sha(HERE/'R5_FROZEN.receipt.json'),no_interim_final_outcome_analysis=True))
    Y=np.zeros((len(names),6,64,4));U=Y.copy();seen=set();failures=defaultdict(list);outcomes=Counter();traces=0
    from shared_rollout_db.src.rollout_db import connect
    with connect(True) as db:
        for c,path in zip(cases,paths):
            r=read(path);assert r['case']==c and r['protocol_sha256']==sha(HERE/'protocol.json');assert sha(Path(r['trace_path']))==r['trace_sha256'];traces+=1;d=db.execute('SELECT * FROM rollout WHERE rollout_uid=?',(c['rollout_uid'],)).fetchone();assert d and not d['conflict_quarantined'];assert all(d[k]==r[k] for k in ['success','deadlock','timeout','collision','numerical_failure']);i=names.index(c['base_controller_name']);a=arms.index(c['arm']);s=c['state_index'];seed=c['seed'];slot=i,a,s,seed;assert slot not in seen;seen.add(slot);Y[slot]=r['success'];U[slot]=r['numerical_failure'];outcomes[r['outcome']]+=1
            if r['outcome']!='success':failures[c['base_controller_name']].append(dict(arm=c['arm'],state_index=s,seed=seed,rollout_uid=c['rollout_uid'],outcome=r['outcome'],occurrence_step=r['error']['step'] if r['error'] else r['episode_length'],error_type=r['error']['type'] if r['error'] else None))
        assert db.execute('SELECT count(*) FROM rollout WHERE experiment_uid=?',(EXP+'_unlabeled',)).fetchone()[0]==0
    assert np.all(Y+U<=1);selectors={c['controller']:c for c in read(HERE/'SELECTOR_MODELS.json')['choices']};result,mrows,arows,erows=statistics(Y,U,names,arms,selectors);np.savez_compressed(HERE/'LABELS.npz',success=Y,unknown=U,controller_names=np.array(names),arms=np.array(arms));csvwrite('ACTIONS_REGRETS.csv',mrows);csvwrite('ARM_RATES.csv',arows);csvwrite('E_L_N.csv',erows);write(HERE/'FAILURE_RECORDS.json',failures)
    predrows=[dict(controller=n,scheme=s,Ehat=float(v['predictions'][i]),true_E=float(v['actual_E'][i]),source_mean_baseline=float(v['source_mean_predictions'][i])) for s,v in result['prediction_metrics'].items() for i,n in enumerate(names)];csvwrite('E_PREDICTIONS.csv',predrows)
    main=result['methods']['primary'];C1=main['C1'];C3=result['prediction_metrics']['primary']['C3']
    if C1=='SUPPORTED' and C3=='SUPPORTED':mapping='PROSPECTIVE_NUMERICAL_CONFIRMATION: schedule plus R5-predicted early component transfers to these new Ring final siblings; not independent training-run or cross-scene confirmation.'
    elif C1=='SUPPORTED' and C3=='REJECTED':mapping='Schedule generalization prospectively confirmed; R5->E relation not confirmed; incremental controller-information value remains separate C2 test.'
    elif C1=='REJECTED':mapping='PROSPECTIVE_CONFIRMATION_FAILED: registered full-process gate failed; inspect per-controller failure types/steps.'
    else:mapping='INCONCLUSIVE: unknown or incomplete cohort prevents frozen joint mapping.'
    post=dict(status='PASS',requests=len(cases),raw=len(paths),unique_slots=len(seen),trace_hashes_verified=traces,missing=0,quarantined=0,unknown=int(U.sum()),outcomes=outcomes,probe_success_rows=0,unknown_never_rerun=True)
    write(HERE/'main_POSTFLIGHT.json',post);result.update(status='NUMERICAL_COMPLETE_PENDING_VIDEO_GATE',C1=C1,C1b=main['C1b'],C2=main['C2'],C3=C3,conclusion_mapping=mapping,C2_headroom_point_pass=main['headroom_point_pass'],controller_order=names,arms=arms,prospective_new_data=True,final_success_generated_only_after_freezes=True,unknown=int(U.sum()),postflight=post,scope='Ring FF horizon700; new64states and never-success-evaluated final siblings; old best/source knowledge DEVELOPMENT; prospective primary excludes sibling; secondary sensitivity only',failures_exceeding5pp={name:failures[name] for name in main['regret_exceeds5pp_point']},label_chronology=dict(prereg=read(HERE/'PREREGISTRATION.receipt.json')['utc'],probe=read(HERE/'R5_FROZEN.receipt.json')['utc'],selector=read(HERE/'SELECTOR_FROZEN.receipt.json')['utc'],endpoint=read(opening)['utc']));write(HERE/'results.json',result)
    print(json.dumps(clean(dict(C1=C1,C1b=result['C1b'],C2=result['C2'],C3=C3,headroom=main['headroom_count'],mean_regret=main['mean_regret'],max_regret=main['max_regret'],gain_vs_F10=main['mean_gain_vs_F10'],prediction=result['prediction_metrics']['primary'],unknown=int(U.sum())))))
if __name__=='__main__':main()
